```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include "Markdown.h" // Hier muss das Header-File Ihres Markdown-Parser-Tools geladen werden

std::string markdownToHtml(const std::string& markdown) {
    std::stringstream ss;
    Markdown md;

    // Parse Markdown-Text und fügen den HTML-Code zum stringstream hinzu
    for (const auto& line : std::string_split(markdown, "\n")) {
        md.feed(line);
        while (!md.done()) {
            ss << md.next();
        }
        md.reset();
        ss << "\n";
    }

    return ss.str();
}

// Helper-Funktion zum Teilen einer Zeichenkette in eine Vektor von Strings
std::vector<std::string> string_split(const std::string& s, char delim) {
    std::stringstream ss(s);
    std::string item;
    std::vector<std::string> tokens;

    while (std::getline(ss, item, delim)) {
        tokens.push_back(item);
    }

    return tokens;
}
