#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int countWordOccurrences(string word, vector<string> lines) {
    int count = 0;
    for (const auto& line : lines) {
        if (count_if(line.begin(), line.end(), [](char c) { return !isspace(c); }) > 0) { // check if line has any non-whitespace characters
            size_t pos = line.find(word);
            while (pos != string::npos) {
                count++;
                pos = line.find(word, pos + 1); // find next occurrence of word in the line
            }
        }
    }
    return count;
}

int main() {
    string filename, word;
    cout << "Enter file name: ";
    cin >> filename;

    ifstream file(filename);
    if (!file.is_open()) {
        cerr << "Error opening file." << endl;
        return 1;
    }

    vector<string> lines;
    string line;
    while (getline(file, line)) {
        lines.push_back(line);
    }

    cout << "Enter word to count occurrences: ";
    cin >> word;

    int occurrences = countWordOccurrences(word, lines);

    cout << "The word \"" << word << "\" appears " << occurrences << " times in the file." << endl;

    file.close();
    return 0;
}
